-- migration: 0004_consent_privacy
-- phase: expand (additive only)
-- Source: docs/data-model.md section 7.6 (consent and privacy), master prompt B1 and section 2.
--
-- Deviations from the data model (additive, noted for review):
--   * market_id has no FK to markets (markets table not built yet); RLS ships with packages/policy.
--   * privacy_requests gains export_object_key (the export_media_id FK target, media_assets, is not built).
--   * privacy_requests.idempotency_key is generated by the service when the caller sends none.
--   * Blocked deletions are rejected with a typed error and leave no row (BLOCKED stays a legal status).
--   * ADR-lite: DeletionService inserts the deletion request directly in COOLING (skipping RECEIVED/VERIFIED)
--     because an authenticated session already counts as verification.
--   * retention_policies is new (not in the data model): drives purgePlan(); the rule codes match the
--     retention_rules keys in data_inventory.yaml where one exists.

CREATE TABLE consent_purposes (
  market_id    text NOT NULL CHECK (length(market_id) > 0),
  code         text NOT NULL CHECK (code IN ('marketing_push', 'marketing_whatsapp', 'marketing_email', 'analytics',
                 'personalization', 'budget_insights', 'measurements', 'location_precise', 'cross_border_ml')),
  version      int  NOT NULL CHECK (version >= 1),
  text_ar      text NOT NULL,
  text_en      text,
  effective_at timestamptz NOT NULL,
  PRIMARY KEY (market_id, code, version)
);

-- Append-only proof. There is deliberately NO default for "granted": nothing is ever pre-granted.
CREATE TABLE consent_records (
  id               uuid PRIMARY KEY,                       -- UUIDv7
  market_id        text NOT NULL CHECK (length(market_id) > 0),
  user_id          uuid REFERENCES users (id),             -- NULL for a visitor (banner)
  device_id        uuid REFERENCES devices (id),
  purpose_code     text NOT NULL CHECK (purpose_code IN ('marketing_push', 'marketing_whatsapp', 'marketing_email',
                     'analytics', 'personalization', 'budget_insights', 'measurements', 'location_precise', 'cross_border_ml')),
  purpose_version  int  NOT NULL CHECK (purpose_version >= 1),
  granted          boolean NOT NULL,
  method           text NOT NULL CHECK (method IN ('banner', 'onboarding', 'settings', 'api')),
  ip_hmac          bytea,
  recorded_at      timestamptz NOT NULL
);
CREATE INDEX consent_records_user_idx ON consent_records (user_id, purpose_code, recorded_at DESC);
CREATE INDEX consent_records_device_idx ON consent_records (device_id, purpose_code, recorded_at DESC);

CREATE FUNCTION consent_records_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'consent_records is append-only (% rejected)', TG_OP USING ERRCODE = 'integrity_constraint_violation';
END $$;
CREATE TRIGGER consent_records_no_change BEFORE UPDATE OR DELETE ON consent_records
  FOR EACH ROW EXECUTE FUNCTION consent_records_append_only();
CREATE TRIGGER consent_records_no_truncate BEFORE TRUNCATE ON consent_records
  FOR EACH STATEMENT EXECUTE FUNCTION consent_records_append_only();

-- Fast gate: projection of the latest record per purpose, written in the same transaction.
CREATE TABLE consent_state (
  user_id          uuid NOT NULL REFERENCES users (id),
  purpose_code     text NOT NULL,
  market_id        text NOT NULL,
  granted          boolean NOT NULL,
  purpose_version  int NOT NULL,
  updated_at       timestamptz NOT NULL,
  PRIMARY KEY (user_id, purpose_code)
);
CREATE INDEX consent_state_purpose_idx ON consent_state (purpose_code, granted);

CREATE TABLE privacy_requests (
  id                 uuid PRIMARY KEY,
  user_id            uuid NOT NULL REFERENCES users (id),
  market_id          text NOT NULL CHECK (length(market_id) > 0),
  kind               text NOT NULL CHECK (kind IN ('export', 'delete', 'rectify', 'restrict', 'object')),
  status             text NOT NULL CHECK (status IN ('RECEIVED', 'VERIFIED', 'BLOCKED', 'COOLING', 'IN_PROGRESS',
                       'COMPLETED', 'CANCELLED', 'REJECTED')),
  blocked_reason     text,
  due_at             timestamptz NOT NULL,
  cooling_until      timestamptz,
  export_media_id    uuid,
  export_object_key  text,
  export_expires_at  timestamptz,
  completed_at       timestamptz,
  idempotency_key    uuid NOT NULL,
  created_at         timestamptz NOT NULL,
  updated_at         timestamptz NOT NULL,
  UNIQUE (user_id, idempotency_key)
);
CREATE INDEX privacy_requests_queue_idx ON privacy_requests (status, due_at);
-- At most one open export and one open deletion per user.
CREATE UNIQUE INDEX privacy_requests_open_uq ON privacy_requests (user_id, kind)
  WHERE status IN ('RECEIVED', 'VERIFIED', 'COOLING', 'IN_PROGRESS') AND kind IN ('export', 'delete');

CREATE TABLE retention_policies (
  code             text PRIMARY KEY,
  table_name       text NOT NULL CHECK (table_name ~ '^[a-z_][a-z0-9_]*$'),
  timestamp_column text NOT NULL CHECK (timestamp_column ~ '^[a-z_][a-z0-9_]*$'),
  retain_for       interval NOT NULL,
  action           text NOT NULL CHECK (action IN ('delete', 'pseudonymise', 'aggregate')),
  verify_ref       text,                                   -- VERIFY BEFORE LAUNCH register id
  note             text NOT NULL
);

